const TRIM_START = compatibleRegex(String.raw`^\s+`);
const TRIM_END = compatibleRegex(String.raw`\s+$`);
const trimStart = text => text.replace(TRIM_START, '');
const trim = text => trimStart(text).replace(TRIM_END, '');
const codepointLength = text => [...text].length;
const CODE_OPERAND = '\ufffc';
const BACKTICK_RUN = /`+/gu;
const CODE_FENCE = /^(?<marker>`{3,}|~{3,})(?<tail>.*)$/u;
const LIST_ITEM_START = /^(?<indent> {0,3})(?<marker>[-*+]|[0-9]+[.)])(?<gap> +)(?<body>.*)$/u;
const TABLE_SEPARATOR_CELL = /^:?-{3,}:?$/u;
const CONJUNCTION_END = compatibleRegex(String.raw`\b(?:and|or)\s*$`, 'i');
const MODAL_END = compatibleRegex(String.raw`\b(?:may|might|could|should|would|must|can|will|shall)(?:n't)?(?:\s+(?:not|never|also|already|just|only|even|still|yet|ever|well|perhaps|\w+ly))*\s*$`, 'i');
const ABBREVIATION_END = compatibleRegex(String.raw`(?:\b(?:[A-Za-z]\.){2,}|\b(?:Mr|Mrs|Ms|Dr|Prof|Sr|Jr|vs|etc|Fig|No)\.)$`, 'i');
const WORD_TOKEN = compatibleRegex(String.raw`[^\s\ufffc]+`, 'g');
const BLOCK_SEPARATOR = compatibleRegex(String.raw`^ {0,3}(?:(?:\* *){3,}|(?:- *){3,}|(?:_ *){3,}|=+)\s*$`);
const HEADING = /^ {0,3}#{1,6}(?: +|$)/u;
const SENTENCE_BOUNDARY = compatibleRegex(String.raw`(?<=[.!?])["'”’)\]}]*\s+`, 'g');
const TEXT_LIMITS = Object.freeze({ instruction: 20, description: 25 });
const SCHEMA_VERSION = 1;
const SYNONYM_GROUPS = [
  ['check', 'verify', 'confirm', 'validate'], ['delete', 'remove', 'erase'],
  ['start', 'launch', 'begin', 'initiate'], ['stop', 'halt', 'terminate'],
  ['show', 'display'], ['use', 'utilize', 'employ'], ['fix', 'repair', 'correct'],
  ['send', 'transmit'], ['get', 'retrieve', 'fetch', 'obtain'], ['change', 'modify', 'alter'],
];

// 中文术语一致性只提示有限词表内的近义词，不判断不同对象或动作是否同义。
const SYNONYM_GROUPS_ZH = [
  ['检查', '核查', '校验'], ['删除', '移除', '清除'],
  ['启动', '开启', '发起'], ['停止', '终止', '停用'],
  ['显示', '展示', '呈现'], ['使用', '采用', '利用'],
  ['修改', '更改', '变更'], ['获取', '读取', '取得'],
  ['发送', '传输', '传送'], ['创建', '新建', '生成'],
];
// 要求强度词用于估计一段中的操作要求数量，不判断它们是否真的对应不同操作。
// 要求强度词只在完整词形下计数；单字「应」「须」会命中「响应」「应用」「必须」等普通词。
const ZH_REQUIREMENT_MODAL = /(?:必须|应当|应该|可以|不得|禁止|需要)/gu;
const ZH_PARAGRAPH_SENTENCE_TARGET = 6;

// 中文规范按汉字与西文词计数；句长上限为项目适配值，与英文词数上限不是换算关系。
const TEXT_LIMITS_ZH = Object.freeze({ instruction: 20, description: 30 });
const ZH_CONJUNCTION_END = /(?:和|或|以及|并且|或者|同时)\s*$/u;
const HAN_CHARACTER = /\p{Script=Han}/u;
const TOKEN_CHARACTER = /[\p{L}\p{N}\p{M}]/u;
const ZH_TOKEN = /[\p{L}\p{N}\p{M}]/gu;
const ZH_SENTENCE_TERMINATOR = /[。！？]/u;
const ZH_SENTENCE_CLOSER = new Set(['”', '’', '」', '』', '）', ')', ']', '】', '》']);

/** 英文按空白切词，返回词数与首词索引。 */
function countTokensEn(text) {
  const tokens = [...matches(WORD_TOKEN, text)];
  return [tokens.length, tokens.length ? tokens[0].index : -1];
}

/** 中文每个汉字计 1，连续西文或数字串计 1，标点与行内代码不计。 */
function countTokensZh(text) {
  let count = 0;
  let first = -1;
  for (const match of matches(ZH_TOKEN, text)) {
    const offset = match.index;
    const previous = offset > 0 ? text[offset - 1] : '';
    const continuesNumber = previous === '.'
      && /[0-9]/u.test(text[offset - 2] ?? '') && /[0-9]/u.test(match[0]);
    // 汉字逐个计；西文串只在它不是紧跟在同类字符之后时计 1。
    if (HAN_CHARACTER.test(match[0])
      || previous === '' || (!TOKEN_CHARACTER.test(previous) && !continuesNumber) || HAN_CHARACTER.test(previous)) {
      if (first < 0) first = offset;
      count += 1;
    }
  }
  return [count, first];
}

/** 英文句边界沿用缩写保护后的 `.`、`!`、`?`。 */
function enSentenceEnds(text) {
  return [...matches(SENTENCE_BOUNDARY, text)]
    // 名称缩写最长 5 个字符；两个末尾字母加点已足以识别点状缩写。
    // 保留前一个 Unicode 字符的空间，避免截断词边界，同时不反复扫描正文前缀。
    .filter(match => !ABBREVIATION_END.test(text.slice(Math.max(0, match.index - 8), match.index)))
    .map(match => match.index + match[0].length);
}

/** 中文按 `。`、`！`、`？` 分句，并允许句末闭合引号或括号。 */
function zhSentenceEnds(text) {
  const ends = [];
  for (let index = 0; index < text.length; index += 1) {
    if (!ZH_SENTENCE_TERMINATOR.test(text[index])) continue;
    let end = index + 1;
    while (end < text.length && ZH_SENTENCE_CLOSER.has(text[end])) end += 1;
    ends.push(end);
  }
  return ends;
}

function matches(pattern, text) {
  const global = pattern.flags.includes('g') ? pattern : new RegExp(pattern.source, `${pattern.flags}g`);
  return text.matchAll(global);
}

class Segment {
  constructor(listId = null) {
    this.text = '';
    this.positions = [];
    this.listId = listId;
  }

  append(text, line, column) {
    if (this.text) {
      this.text += ' ';
      this.positions.push([line, column]);
    }
    this.text += text;
    let offset = 0;
    for (const character of text) {
      // UTF-16 的两个单元共享同一个 Unicode 字符列号。
      for (let unit = 0; unit < character.length; unit += 1) this.positions.push([line, column + offset]);
      offset += 1;
    }
  }
}

/** 每个代码字符替换一个操作数，并同步调整 UTF-16 索引到原始位置的映射。 */
function maskInlineCode(text, positions = Array.from({ length: text.length }, (_, index) => index)) {
  let masked = '';
  const mapped = [];
  let previous = 0;
  const runs = [...matches(BACKTICK_RUN, text)];
  for (let runIndex = 0; runIndex < runs.length; runIndex += 1) {
    const opening = runs[runIndex];
    let escapes = 0;
    while (text[opening.index - escapes - 1] === "\\") escapes += 1;
    const markerLength = opening[0].length - escapes % 2;
    if (!markerLength) continue;
    const closingIndex = runs.findIndex((run, index) => index > runIndex && run[0].length === markerLength);
    if (closingIndex < 0) continue;
    const start = opening.index + escapes % 2;
    const end = runs[closingIndex].index + markerLength;
    masked += text.slice(previous, start);
    for (let index = previous; index < start; index += 1) mapped.push(positions[index]);
    let index = start;
    for (const character of text.slice(start, end)) {
      masked += CODE_OPERAND;
      mapped.push(positions[index]);
      index += character.length;
    }
    previous = end;
    runIndex = closingIndex;
  }
  masked += text.slice(previous);
  for (let index = previous; index < positions.length; index += 1) mapped.push(positions[index]);
  return [masked, mapped];
}

const leadingSpaces = line => line.length - line.replace(/^ +/u, '').length;

function splitTableRow(line) {
  let left = codepointLength(line) - codepointLength(trimStart(line));
  let content = trim(line);
  if (!content.includes('|')) return null;
  const hasOuterPipe = content.startsWith('|') || (content.endsWith('|') && !content.endsWith('\\|'));
  if (content.startsWith('|')) {
    content = content.slice(1);
    left += 1;
  }
  if (content.endsWith('|') && !content.endsWith('\\|')) content = content.slice(0, -1);
  const [masked, offsets] = maskInlineCode(content);
  const cuts = [...matches(/(?<!\\)\|/gu, masked)].map(match => offsets[match.index]);
  if (!cuts.length && !hasOuterPipe) return null;
  const cells = [];
  let start = 0;
  for (const end of [...cuts, content.length]) {
    const raw = content.slice(start, end);
    const leading = codepointLength(raw) - codepointLength(trimStart(raw));
    cells.push([trim(raw), left + codepointLength(content.slice(0, start)) + leading]);
    start = end + 1;
  }
  return cells;
}

function splitLines(text) {
  if (!text) return [];
  const lines = text.split(/\r\n|[\n\r\v\f\u001c-\u001e\u0085\u2028\u2029]/u);
  if (lines.at(-1) === '') lines.pop();
  return lines;
}

function segmentsFor(text) {
  const lines = splitLines(text);
  const segments = [];
  const items = [];
  let current = null;
  let activeItem = null;
  let fence = null;
  let tableWidth = null;
  const flush = () => {
    if (current !== null && trim(current.text)) {
      [current.text, current.positions] = maskInlineCode(current.text, current.positions);
      segments.push(current);
      if (current.listId !== null) items[current.listId].segments.push(current);
    }
    current = null;
  };
  for (let index = 0; index < lines.length; index += 1) {
    const raw = lines[index];
    const line = index + 1;
    const indent = leadingSpaces(raw);
    const stripped = raw.slice(indent);
    const fenceMatch = CODE_FENCE.exec(stripped);
    if (fence !== null) {
      if (fenceMatch && fenceMatch.groups.marker[0] === fence[0]
          && fenceMatch.groups.marker.length >= fence[1] && !trim(fenceMatch.groups.tail)
          && indent <= fence[2] + 3) fence = null;
      continue;
    }
    const fenceIndent = activeItem === null ? 0 : items[activeItem].contentIndent;
    if (fenceMatch && indent <= fenceIndent + 3
        && (fenceMatch.groups.marker[0] !== '`' || !fenceMatch.groups.tail.includes('`'))) {
      flush();
      tableWidth = null;
      fence = [fenceMatch.groups.marker[0], fenceMatch.groups.marker.length, indent >= fenceIndent ? fenceIndent : 0];
      continue;
    }
    if (!trim(raw)) {
      flush();
      tableWidth = null;
      continue;
    }
    const start = LIST_ITEM_START.exec(raw);
    const continuation = activeItem !== null && !start && indent >= items[activeItem].contentIndent;
    if (!continuation) activeItem = null;
    const codeIndent = continuation ? items[activeItem].contentIndent + 4 : 4;
    const indented = indent >= codeIndent || raw.startsWith('\t');
    if (indented && (current === null || continuation)) {
      flush();
      tableWidth = null;
      continue;
    }
    const heading = HEADING.exec(raw);
    const separatorBlock = BLOCK_SEPARATOR.test(raw);
    const row = !indented && !start && !heading && !separatorBlock ? splitTableRow(raw) : null;
    if (!row || row.length !== tableWidth) tableWidth = null;
    if (row && tableWidth === null && index + 1 < lines.length) {
      const next = lines[index + 1];
      const separator = leadingSpaces(next) < codeIndent && !next.startsWith('\t')
        ? splitTableRow(next) : null;
      if (separator && separator.length === row.length
          && separator.every(([cell]) => TABLE_SEPARATOR_CELL.test(cell))) {
        tableWidth = row.length;
        index += 1;
      }
    }
    if (tableWidth !== null) {
      flush();
      for (const [cell, column] of row) {
        const segment = new Segment(activeItem);
        segment.append(cell, line, column + 1);
        [segment.text, segment.positions] = maskInlineCode(segment.text, segment.positions);
        segments.push(segment);
        if (activeItem !== null) items[activeItem].segments.push(segment);
      }
      continue;
    }
    if (separatorBlock) {
      flush();
      continue;
    }
    let body;
    let column;
    if (start) {
      flush();
      activeItem = items.length;
      const bodyIndex = start.groups.indent.length + start.groups.marker.length + start.groups.gap.length;
      items.push({ markerPosition: [line, start.groups.indent.length + 1], contentIndent: bodyIndex, segments: [] });
      current = new Segment(activeItem);
      body = start.groups.body;
      column = bodyIndex + 1;
    } else if (heading) {
      flush();
      body = raw.slice(heading[0].length);
      column = heading[0].length + 1;
      current = new Segment();
    } else {
      if (current === null || current.listId !== activeItem) {
        flush();
        current = new Segment(activeItem);
      }
      body = trimStart(raw);
      column = codepointLength(raw) - codepointLength(body) + 1;
    }
    current.append(body, line, column);
    if (heading) flush();
  }
  flush();
  return { segments, items };
}

function regexChecker(pattern, protectModal = false) {
  return function* check(context) {
    for (const segment of context.segments) {
      for (const match of matches(pattern, segment.text)) {
        if (protectModal && match[1].toLowerCase() === 'have' && MODAL_END.test(segment.text.slice(0, match.index))) continue;
        yield { position: segment.positions[match.index], match: match[0] };
      }
    }
  };
# 检查器：CLI、能力与边界

本文是 `scripts/ste-lint.mjs` 的接口与机械检查能力说明。英文改写规则以 [SKILL.md](../SKILL.md) 为准，中文改写规则以[中文简明技术写作规范](chinese-writing-rules.md)为准。检查器仅依赖 Node.js 22 或更高版本的内置模块，不需要 npm 依赖，不调用模型、外部词典或 NLP 服务。

## 输入与 CLI

检查文件，也可以不传文件名而从标准输入读取：

```bash
node scripts/ste-lint.mjs --text-type instruction instructions.md
node scripts/ste-lint.mjs --text-type description description.md
node scripts/ste-lint.mjs --language zh --text-type instruction zh-instructions.md
node scripts/ste-lint.mjs --language zh --list-rules
printf '%s\n' 'The job may have failed.' | node scripts/ste-lint.mjs --json
node scripts/ste-lint.mjs --baseline 5 legacy.md
node scripts/ste-lint.mjs --disable passive-voice,present-perfect text.md
node scripts/ste-lint.mjs --list-rules
node scripts/ste-lint.mjs --list-rules --json
node scripts/ste-lint.mjs --selftest
```

| 参数 | 含义 |
|---|---|
| `FILE [FILE ...]` | 以 UTF-8 读取一个或多个文件；省略时读取标准输入。 |
| `--text-type instruction` | 所有输入按指令检查，单句上限为 20 词。 |
| `--text-type description` | 所有输入按说明检查，单句上限为 25 词；这是默认值。 |
| `--language en` | 使用英文规则与词数上限；这是默认值。 |
| `--language zh` | 使用中文规则与字数上限（指令 20 字、说明 30 字）。 |
| `--json` | 输出结构化结果。检查报告包含 `schema_version`（整数 `1`）、`language`、`text_type`、`max_words`、`violations`、`count`、`hard_count`、`baseline`、`words` 和 `per_100_words`。 |
| `--baseline N` | 允许硬性问题总数不超过非负整数 `N`；默认 `0`。 |
| `--disable rule1,rule2` | 按规则 ID 禁用检查。规则 ID 以 `--list-rules` 为准；未知 ID 或空项会报参数错误。 |
| `--list-rules` | 显示规则 ID、等级及能力说明，可与 `--json` 配合。 |
| `--selftest` | 使用 `node:test` 运行 `tests/test_ste_lint.mjs`，只覆盖 Node 检查器回归。 |

文本类型由调用方选择，检查器不会自动识别指令或推断 Strict 模式。混合文档应拆成不同输入并分别设置类型。语言同样由调用方用 `--language` 选择，不自动识别；`en` 使用英文规则与词数上限，`zh` 使用中文规则与字数上限。

`--selftest` 必须单独使用；`--list-rules` 仅可与 `--json` 和 `--language` 组合。两种操作互斥，都不能携带文件、`--baseline`、`--disable` 或 `--text-type`；即使显式传入默认值也会报错。无效组合返回 `2`，不会忽略选项后继续运行。普通文本检查可以组合这些检查参数。

正常检查时，硬性问题总数超过基准返回退出码 `1`，否则返回 `0`。advisory 不增加硬性问题数。参数或输入错误返回退出码 `2`，并提供错误说明。

## 规则等级

运行时的规则 ID、等级、类型和限制以 `--list-rules` 返回的统一元数据为准。下表解释当前规则的能力，不作为另一份规则配置维护。

每条规则同时登记元数据和可调用的执行器，`lint()` 统一执行目录中的检查器。登记时拒绝缺失执行器和重复 ID，新增规则不能只出现在帮助中而不参与检查。

“硬性”指确定出现受支持的形式，不代表判断出语义错误或官方 STE 不合规。结构化结果保留等级名称 `advisory-free`（硬性）和 `advisory`（建议）；规则类型为 `deterministic` 或 `heuristic`。`--list-rules --json` 输出 `schema_version` 和 `rules`，每条规则含 `id`、`level`、`type`、`description`、`limitations`。

| 规则 ID | 等级 | 检查内容与限制 |
|---|---|---|
| `semicolon` | 硬性 | 正文分号；代码区域不参与检查。 |
| `long-sentence` | 硬性 | 正文句子超过选定文本类型的词数上限；句子切分是启发式处理。 |
| `dangling-conjunction` | 硬性 | 受支持列表项末尾的英文 `and` 或 `or`；不判断完整句法。 |
| `phrasal-verb` | advisory | 内置的有限短语动词模式，不涵盖所有英语短语动词。 |
| `nominalization` | advisory | 内置动作名词化模式，不进行完整词性或语义分析。 |
| `marketing-adjective` | advisory | 提示部分质量主张；不能证明没有依据，也不能要求删掉原文程度或虚构数据。 |
| `passive-voice` | advisory | 正则识别可能的被动语态；不猜测 actor，也可能匹配形容词。 |
| `present-perfect` | advisory | 正则识别部分复合时态；保护部分情态完成式，如 `may have failed`，不是完整语法分析。 |
| `synonym-rotation` | advisory | 文件内出现词表中的多个近义词时提示；不能确认它们描述同一概念、对象或动作。 |

`--language zh` 启用下列中文规则。中文规范、计数口径和完整规则见[中文简明技术写作规范](chinese-writing-rules.md)。

| 规则 ID | 等级 | 检查内容与限制 |
|---|---|---|
| `zh-semicolon` | 硬性 | 正文含全角 `；` 或半角 `;`；代码区域不参与检查。 |
| `zh-long-sentence` | 硬性 | 句子字数超过中文上限；按汉字与西文词计数，按 `。！？` 分句，不实现完整中文语法分析。 |
| `zh-dangling-conjunction` | advisory | 启发式提示受支持列表项末尾的连接词（和、或、以及、并且、或者、同时）；后缀匹配无法确定中文词边界，会误报「总和」「饱和」等词，不影响退出码。 |
| `zh-list-required` | advisory | 一段中出现三个或更多要求强度词（必须、应当、可以、不得等）时提示改为列表；不判断要求是否真的对应不同操作。 |
| `zh-paragraph-topic` | advisory | 段落句子数超过 6 句目标时提示分段或合并；按 `。！？` 计数，不判断主题是否真的不同。 |
| `zh-multi-action` | advisory | 句内出现并列连接词时提示可能包含多个动作；不判断分句是否真的表示不同动作。 |
| `zh-nominalization` | advisory | 有限动词加双字名词模式；不进行词性分析。 |
| `zh-marketing-adjective` | advisory | 内置空泛修饰语词表；不能证明没有依据，也不能要求删除原文程度或虚构数据。 |
| `zh-passive` | advisory | 正则识别 `被`、`受到`、`遭到` 等被动表达；可能匹配名词或固定搭配。 |
| `zh-barrier-phrase` | advisory | 内置无信息引导语词表；不能判断该表达是否承载语气或衔接功能。 |
| `zh-synonym-rotation` | advisory | 文件内出现词表中的多个中文近义词时提示；不能确认它们描述同一概念、对象或动作。 |

例如 `Start the service. Launch the browser.` 可以触发近义词提示，但两个动作语境不同，不能据此强制改成同一动词。advisory 应结合原文判断，不能通过自动替换直接“修复”。

## 计数与源位置

正文按空白分隔计算词数，标点不单独计词。排除代码围栏、缩进代码、inline code、列表标记、ATX 标题开头的 `#` 标记、表格分隔行及水平线或 Setext 分隔行。行内代码视为不计词的独立操作数，防止其两侧单词被正则拼接成新的短语。

中文不按空白分词：每个汉字计 1，连续西文或数字串整体计 1；两个数字之间的半角小数点保留在串内，`3.14`、`v2.1`、`v2.1.3` 各计 1。空白或其他标点断开连续串，`HTTP v2.1`、`API.HTTP` 各计 2；汉字不与相邻西文串合并。标点与空白本身不计，行内代码同样不计数。因此 `words` 和 `per_100_words` 在 `--language zh` 下的单位是「字」，与英文词数不可互换。句长要求的适用范围见[中文规范](chinese-writing-rules.md#计数口径)；检查器不自动判断输入是否为解释性长文。

段落内的软换行合并后检查句长，不能通过将一个长句拆成多个物理行规避阈值。空行与 Markdown 块边界分隔检查单元。普通标题正文和表格正文单元格也参与检查。

行号和列号指向**原始输入**，从 `1` 开始；列号按 Unicode code point 计算，不是终端显示宽度。跨行问题定位到该问题在原文中的起始位置。删除或遮蔽 inline code 后不会把其后的报告位置左移。

## 支持的 Markdown 子集

- 列表标记前允许 `0` 至 `3` 个空格；支持 `-`、`*`、`+`、数字加 `.` 或 `)`；标记后使用 ASCII 空格。按标记及间隔宽度识别续行，检查最后一条有效内容是否为悬空连词。
- 围栏使用反引号或波浪号，开启与关闭标记必须各占独立物理行，前面仅有空格缩进。关闭围栏必须与开启围栏使用相同字符，且长度至少相同；围栏内另一种字符不会结束当前围栏。
- 忽略围栏代码和受支持的缩进代码；普通段落未被空行或块边界终止时，四空格或 Tab 开头的续行仍合并检查。空行后的缩进代码继续忽略；列表内按列表内容缩进识别代码。
- inline code 使用等长反引号串开启和关闭，允许跨行及包含不同长度的反引号串。开启处连续反斜杠按奇偶决定是否转义第一个反引号；代码内部反斜杠不转义闭合标记。代码不参与词语检查，后续报告仍使用原始行列号。
- 常见 pipe 表格在正文块状态下通过表头及紧随的分隔行识别，支持列表内另起行且按内容缩进的表格。列数相同的正文行按单元格分别检查；表格分隔行不参与正文检查。代码块内的表头不影响正文；空行、列表标记、标题、水平线、代码块或列数不符的行结束表格。

它不是完整 CommonMark 解析器。引用块内的列表、使用 Tab 分隔标记的列表、懒惰续行和完整嵌套列表语义不在支持范围内。列表标记同一行直接开启的围栏（例如 `- ```python`）不受支持；应将开启围栏另起一行并按列表内容缩进。ATX 标题可选的结尾 `#` 标记不会去除，因此可能计入词数。缩写、小数、复杂嵌套结构等可能影响句子切分或分段，不应将解析结果视为正式语言学分析。

## 检查器不能证明的事项

检查器不比较原文与改写稿，因此不验证事实、条件、数量、否定、要求强度、时间关系或 actor 是否保持。它也不检查所有技能规则，例如名词堆叠、每句一条指令、段落主题及安全条件覆盖范围，更不核验官方批准词典。

结果为零只表示当前启用规则在受支持输入范围内没有发现问题。用户应按技能的保真流程对照原文；合法的保真例外可以保留并在用户要求分析时说明。

